using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;using LWS.TruckCheeseRolling;using LWS.TruckTaxi;
namespace LWS.TruckMattressRacing.Editor {public static class MattressProductionAuthoring {
 public static void Install(MattressMatch m){if(m.world!=null)return;var root=new GameObject("Seeded physical mattress event world");var world=root.AddComponent<MattressWorld>();m.world=world;world.match=m;var obstacles=new List<MattressObstacle>();var destination=SceneManager.GetActiveScene();var cheese=EditorSceneManager.OpenScene("Assets/TruckCheeseRolling/Scenes/TruckCheeseRolling.unity",OpenSceneMode.Additive);GameObject sheep=null;try{SceneManager.SetActiveScene(destination);var source=cheese.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CheeseSheep>(true)).First();sheep=UnityEngine.Object.Instantiate(source.modelSlot.gameObject);SceneManager.MoveGameObjectToScene(sheep,destination);}finally{EditorSceneManager.CloseScene(cheese,true);SceneManager.SetActiveScene(destination);}
