 else{int variant=i/4%6;o.kind=variant==4?MattressObstacleKind.Fence:MattressObstacleKind.Loose;string path=variant==0?"Assets/RoadPropsPack/URP/Prefabs/TrashBin_URP.prefab":variant==1?"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Barrel01 Variant.prefab":variant==2?"Assets/RoadPropsPack/URP/Prefabs/TrafficCone_URP.prefab":variant==3?"Assets/RoadPropsPack/URP/Prefabs/TireStacked01_URP.prefab":variant==4?"Assets/JC_LP_MegaCity/Prefabs/FloorProps/SM_FloorProps_Fence_01.prefab":"Assets/ConstructionPropsBundle/URP/Prefabs/SM_Pallet Variant.prefab";var size=variant==4?new Vector3(4,1.2f,.3f):new Vector3(1.3f,1.2f,1.3f);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder.transform,path,size,0,false,"TruckMattressRacing");foreach(var c in holder.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);var shape=holder.AddComponent<BoxCollider>();shape.center=Vector3.up*.6f;shape.size=size;o.shape=shape;o.body.mass=variant==2?1:variant==3?4:8;}obstacles.Add(o);}
